import sys

MOD = 1_000_000_007

def fib(n):
    if n == 0:
        return 0
    a, b = 0, 1
    for i in range(n.bit_length() - 1, -1, -1):
        c = a * ((b << 1) - a) % MOD
        d = (a * a + b * b) % MOD
        if (n >> i) & 1:
            a, b = d, (c + d) % MOD
        else:
            a, b = c, d
    return a

if __name__ == '__main__':
    print(fib(int(sys.argv[1])))
